-- ==========================================================
-- ملف مولّد تلقائياً من lib/estimation — متعدّلوش بإيدك، عدّل الكود وشغّل npm run seed:generate
-- أسعار تقديرية من السوق المصري (سبتمبر 2026) — is_sample = true معناها "تقديري"، وكلها قابلة للتعديل من الكتالوج
-- ==========================================================
begin;

on conflict (code) do update set group_code = excluded.group_code, title = excluded.title, kind = excluded.kind,
  unit = excluded.unit, measure_unit = excluded.measure_unit, default_waste_pct = excluded.default_waste_pct;

on conflict (id) do update set category_code = excluded.category_code, brand = excluded.brand, model = excluded.model, name = excluded.name,
  unit = excluded.unit, coverage = excluded.coverage, sold_by_pack = excluded.sold_by_pack, is_default = excluded.is_default;

-- الأسعار التقديرية (أي سعر تدخله الشركة بعد كده بياخد الأولوية)
delete from product_prices where owner_id is null and product_id in (select id from products where is_sample and owner_id is null);

commit;
